package net.valor.world.level.biome;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.biome.Biome;
import net.valor.Valor;

/**
 * Keys of Valor's biomes. Counterpart to vanilla's {@link net.minecraft.world.level.biome.Biomes}.
 * <p>
 * Biomes are data (a dynamic registry): their contents are generated by
 * {@code ValorBiomeData} (datagen) into {@code data/valor/worldgen/biome/}. Placement in the
 * Overworld is handled by {@code OverworldBiomeBuilderMixin} and {@link WhisperingWoodsRegions}.
 */
public final class ValorBiomes {

	/** Ancient, dense spruce forest. Rare: replaces whole Dark Forest regions, see {@link WhisperingWoodsRegions}. */
	public static final ResourceKey<Biome> WHISPERING_WOODS = register("whispering_woods");

	private ValorBiomes() {}

	private static ResourceKey<Biome> register(String name) {
		return ResourceKey.create(Registries.BIOME, Valor.id(name));
	}
}
